/** Replies generated by a terminal emulator for its own tmux attachment.
 * They must never be sent as keystrokes into the shared human shell.
 * Keep this allowlist narrow: one complete numeric DA/mode or RGB reply only.
 */
export function isTerminalProtocolReply(data: unknown): data is string {
  if (typeof data !== "string" || data.length > 128) return false;
  return /^\x1b\[(?:[?>]?[0-9]+(?:;[0-9]+)*c|\?[0-9]+;[0-9]+\$y)$/.test(data)
    || /^\x1b\](?:4;[0-9]+|1[012]);rgb:[0-9a-f]{1,4}\/[0-9a-f]{1,4}\/[0-9a-f]{1,4}(?:\x07|\x1b\\)$/i.test(data);
}
